<template><div class="toolbar"><a-button type="primary" @click="create"><PlusOutlined/>立即备份</a-button><span class="muted">共 {{total}} 条记录</span></div><a-card class="panel-card"><a-table :loading="loading" :data-source="records" :columns="columns" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.key==='time'">{{formatTime(record.created_at)}}</template><template v-if="column.key==='status'"><a-tag :color="record.status==='completed'?'success':record.status==='failed'?'error':'processing'">{{record.status}}</a-tag></template><template v-if="column.key==='size'">{{formatSize(record.file_size)}}</template><template v-if="column.key==='action'"><a-button type="link" :href="`/api/backup/download/${record.id}`"><DownloadOutlined/>下载</a-button></template></template></a-table></a-card></template><script setup lang="ts">import{onMounted,ref}from'vue';import{message}from'ant-design-vue';import{PlusOutlined,DownloadOutlined}from'@ant-design/icons-vue';import{get,post}from'../../services/http';import{formatSize,formatTime}from'../../core/format';import type{AnyMap,BackupRecord}from'../../types';const records=ref<BackupRecord[]>([]),total=ref(0),loading=ref(true),columns=[{title:'创建时间',key:'time'},{title:'类型',dataIndex:'backup_type'},{title:'状态',key:'status'},{title:'文件大小',key:'size'},{title:'耗时（秒）',dataIndex:'backup_duration'},{title:'操作',key:'action'}];async function load(){loading.value=true;try{const d=await get<AnyMap>('/backup/list?page=1&page_size=100');records.value=d.list||[];total.value=Number(d.total||0)}finally{loading.value=false}}async function create(){await post('/backup/create',{reason:'前端手动备份'});message.success('备份任务已启动');setTimeout(load,800)}onMounted(load)</script>
